 (() => {
 const roomTypes={core:{name:'Dungeon Core',icon:'🔮',cost:[0,0],desc:'The beating heart of your empire.'},hall:{name:'Goblin Den',icon:'👺',cost:[24,8],desc:'Train goblins. +2 defense and +2 gold each day.'},mine:{name:'Deep Mine',icon:'⛏️',cost:[18,12],desc:'A rich vein of ore. +5 stone each day.'},vault:{name:'Gold Vault',icon:'🪙',cost:[30,10],desc:'A secure treasury. +8 gold each day.'},farm:{name:'Mushroom Farm',icon:'🍄',cost:[20,8],desc:'Feed your growing forces. +6 provisions each day.'},barracks:{name:'War Barracks',icon:'⚔️',cost:[35,22],desc:'Harden your defenses. +12 defense.'},entrance:{name:'Hidden Entrance',icon:'🚪',cost:[0,0],desc:'The concealed way to the surface.'}};
 const initial={day:1,gold:80,stone:45,food:30,renown:12,threat:18,hp:100,goblins:3,raidDone:false,rooms:{'1,2':'entrance','3,2':'core','4,2':'vault','2,2':'hall'},events:[]};
-let s;try{s=JSON.parse(localStorage.getItem('understone-save'))||initial}catch{s=initial}
+let s;try{s=JSON.parse(localStorage.getItem('understone-save'))||JSON.parse(JSON.stringify(initial))}catch{s=JSON.parse(JSON.stringify(initial))}
