 const $=id=>document.getElementById(id); const save=()=>localStorage.setItem('understone-save',JSON.stringify(s));
 function log(text){s.events.unshift({day:s.day,text});s.events=s.events.slice(0,8)}
 function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}

