 const grid=$('mapGrid');grid.innerHTML='';for(let y=0;y<5;y++)for(let x=0;x<7;x++){let key=`${x},${y}`,type=s.rooms[key],cell=document.createElement('button');cell.className=`cell ${type?'room '+type:'empty'} ${selectedCell===key?'selected':''}`;cell.setAttribute('aria-label',type?roomTypes[type].name:'Empty chamber');cell.innerHTML=type?`<span class="glyph">${roomTypes[type].icon}</span><span class="cell-label">${roomTypes[type].name}</span>${type!=='core'&&type!=='entrance'?'<span class="level">I</span>':''}`:'<span class="plus">+</span>';cell.onclick=()=>type?selectRoom(key,type):openBuild(key);grid.appendChild(cell)}
 $('raidBtn').disabled=s.raidDone||s.goblins<1;$('raidBtn').textContent=s.raidDone?'RAID COMPLETE ✓':s.goblins<1?'NEED A GOBLIN':'SEND RAID PARTY  →';$('missionBadge').textContent=s.raidDone?'COMPLETE':'AVAILABLE';$('eventLog').innerHTML=s.events.length?s.events.map(e=>`<div class="event"><b>D${String(e.day).padStart(2,'0')}</b>${e.text}</div>`).join(''):'<div class="event">The chronicle begins with your reign.</div>';$('recruitBtn').disabled=s.gold<18||s.food<5;
 if(s.renown>=100)endGame(true);if(s.hp<=0)endGame(false);save()}
 function selectRoom(key,type){selectedCell=key;render();notify(`${roomTypes[type].name} · ${roomTypes[type].desc}`)}
-function openBuild(key){selectedCell=key;$('modalTitle').textContent=`Build in chamber ${key.split(',').map(n=>Number(n)+1).join(' · ')}`;let options=$('roomOptions');options.innerHTML='';['hall','mine','vault','farm','barracks'].forEach(id=>{let t=roomTypes[id],b=document.createElement('button');b.className='room-option';b.disabled=s.gold<t.cost[0]||s.stone<t.cost[1];b.innerHTML=`<span class="ico">${t.icon}</span><span><b>${t.name}</b><small>${t.desc}</small></span><em>${t.cost[0]}◈ &nbsp;${t.cost[1]}⬟</em>`;b.onclick=()=>build(key,id);options.appendChild(b)});$('buildModal').classList.add('open')}
+function openBuild(key){const [x,y]=key.split(',').map(Number);const connected=Object.keys(s.rooms).some(k=>{const [rx,ry]=k.split(',').map(Number);return Math.abs(rx-x)+Math.abs(ry-y)===1});if(!connected){notify('Clear chambers from your existing halls outward.');return}selectedCell=key;$('modalTitle').textContent=`Build in chamber ${key.split(',').map(n=>Number(n)+1).join(' · ')}`;let options=$('roomOptions');options.innerHTML='';['hall','mine','vault','farm','barracks'].forEach(id=>{let t=roomTypes[id],b=document.createElement('button');b.className='room-option';b.disabled=s.gold<t.cost[0]||s.stone<t.cost[1];b.innerHTML=`<span class="ico">${t.icon}</span><span><b>${t.name}</b><small>${t.desc}</small></span><em>${t.cost[0]}◈ &nbsp;${t.cost[1]}⬟</em>`;b.onclick=()=>build(key,id);options.appendChild(b)});$('buildModal').classList.add('open')}
 function build(key,type){let t=roomTypes[type];if(s.gold<t.cost[0]||s.stone<t.cost[1])return notify('Not enough resources.');s.gold-=t.cost[0];s.stone-=t.cost[1];s.rooms[key]=type;s.renown+=3;log(`${t.name} raised beneath the mountain.`);$('buildModal').classList.remove('open');notify(`${t.name} built · +3 renown`);render()}
 function recruit(){if(s.gold<18||s.food<5)return notify('Need 18 gold and 5 provisions.');s.gold-=18;s.food-=5;s.goblins++;log('A goblin raider joined your garrison.');notify('Goblin recruited. Your defenses grow.');render()}
 function raid(){if(s.raidDone||s.goblins<1)return;s.goblins--;s.gold+=32;s.renown+=14;s.threat=Math.min(100,s.threat+9);s.raidDone=true;log('Raiders ambushed the Moonlit Road. The spoils are yours.');notify('Raid successful · +32 gold · +14 renown');render()}
 function nextDay(){const r=rates();s.day++;s.gold+=r.gold;s.stone+=r.stone;s.food+=r.food;if(s.goblins>1){s.food-=Math.ceil(s.goblins/3)}s.threat=Math.min(100,s.threat+5);s.raidDone=false;log(`Day ${s.day} dawns. Your domain yields ${r.gold} gold and ${r.stone} stone.`);if(s.day%4===0){const power=Math.floor(s.threat*.55)+10,guard=strength();if(guard>=power){s.renown+=8;s.gold+=12;log(`Adventurers repelled (${guard} vs ${power}). The legend of your lair grows.`);notify(`Invasion repelled! +8 renown · +12 gold`)}else{let damage=Math.min(40,power-guard+8);s.hp=Math.max(0,s.hp-damage);s.gold=Math.max(0,s.gold-10);log(`Adventurers breached your halls. Core takes ${damage}% damage.`);notify(`Invasion! Core damaged by ${damage}%. Strengthen your garrison.`)}}if(s.food<0){s.food=0;s.goblins=Math.max(1,s.goblins-1);log('Provisions ran out. A goblin deserted your lair.');}if(s.day%3===0){s.renown+=2;log('Your growing influence earns +2 renown.')}render()}

